package com.collabspace.websocket;
import com.collabspace.dto.MessageDtos.*; import com.collabspace.service.MessageService; import lombok.RequiredArgsConstructor; import org.springframework.messaging.handler.annotation.*; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Controller; import java.security.Principal; import java.util.*;
@Controller @RequiredArgsConstructor public class ChatWebSocketController {private final MessageService messages;private final SimpMessagingTemplate broker; @MessageMapping("/chat.send") public void chat(@Payload SendMessageRequest req,@Header("channelId") String channelId){MessageResponse saved=messages.send(UUID.fromString(channelId),req);broker.convertAndSend("/topic/channel/"+channelId,saved);} @MessageMapping("/typing") public void typing(@Payload Map<String,Object> payload,@Header("channelId")String channelId,Principal p){Map<String,Object> event=new HashMap<>(payload);event.put("username",p==null?"Someone":p.getName());broker.convertAndSend("/topic/channel/"+channelId+"/typing",event);} }
